  function playerSafeState(state){return {schema:'universal.player-safe-project.v8',project:{projectId:state.project.projectId,name:state.project.name,description:state.project.description,era:state.project.era,calendar:state.project.calendar},worldContext:state.worldContext,settlements:state.settlements,locations:state.locations.map(publicLocation),npcs:state.npcs.map(publicNpc),factions:state.factions.filter(x=>x.visibility!=='secret').map(publicFaction),quests:state.quests.filter(x=>x.visibility!=='secret').map(publicQuest),conversations:publicConversations(state)};}
