  async function docxBlob(state){if(!global.JSZip)throw new Error('JSZip is required for DOCX export.');const zip=new JSZip();const paragraphs=[];const add=(text,style)=>paragraphs.push(`<w:p>${style?`<w:pPr><w:pStyle w:val="${style}"/></w:pPr>`:''}<w:r><w:t xml:space="preserve">${xmlEsc(text)}</w:t></w:r></w:p>`);add(state.project.name,'Title');add('UniversalSimulator DM Campaign Guide','Subtitle');add(state.project.description||'');add(`Era ${state.project.era}; context ${state.worldContext?.contextWorldId||state.worldContext?.worldId||'unspecified'}`);add('Settlements','Heading1');for(const s of state.settlements||[]){add(s.name,'Heading2');add(`${s.type}; population ${s.population}; danger ${s.dangerLevel}; biomes ${(s.biomes||[]).join(', ')}`);}add('Locations','Heading1');for(const l of state.locations||[]){add(l.name,'Heading2');add(`${l.category||l.type}. ${l.public?.description||''}`);if(l.secrets?.length)add(`DM secrets: ${l.secrets.join('; ')}`);}add('NPCs','Heading1');for(const n of state.npcs||[]){add(n.name,'Heading2');add(`${n.raceName||''} ${n.profession||''}. ${n.public?.description||''}`);add(`Covenant: ${n.covenantEngine?.className||'Civilian'} ${n.covenantEngine?.subclassName||''}; ${n.covenantEngine?.alignmentProfile||''}`);if(n.private?.secrets?.length)add(`DM secrets: ${n.private.secrets.join('; ')}`);}zip.file('[Content_Types].xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/></Types>');zip.folder('_rels').file('.rels','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>');zip.folder('word').file('document.xml',`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>${paragraphs.join('')}<w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="720" w:right="720" w:bottom="720" w:left="720"/></w:sectPr></w:body></w:document>`).file('styles.xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/></w:style><w:style w:type="paragraph" w:styleId="Title"><w:name w:val="Title"/><w:rPr><w:b/><w:sz w:val="36"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Subtitle"><w:name w:val="Subtitle"/><w:rPr><w:i/><w:sz w:val="24"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Heading1"><w:name w:val="heading 1"/><w:rPr><w:b/><w:sz w:val="30"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Heading2"><w:name w:val="heading 2"/><w:rPr><w:b/><w:sz w:val="24"/></w:rPr></w:style></w:styles>');return zip.generateAsync({type:'blob',compression:'DEFLATE',compressionOptions:{level:6}});}
  async function sha256(content){const bytes=content instanceof Uint8Array?content:new TextEncoder().encode(String(content));if(global.crypto?.subtle){const hash=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join('');}let h=2166136261;for(const b of bytes){h^=b;h=Math.imul(h,16777619);}return `fnv1a-${(h>>>0).toString(16)}`;}
